<!doctype html><html><head><meta charset='utf-8'><meta name='viewport' content='width=device-width,initial-scale=1'><title>Login</title><link rel='stylesheet' href='/assets/css/ui.css'><link rel='stylesheet' href='/assets/css/components.css'><link rel='stylesheet' href='https://cdnjs.cloudflare.com/ajax/libs/font-awesome/6.5.2/css/all.min.css'></head><body>
<div class='page' style='max-width:460px;margin-top:12vh'><div class='glass-card'><h2><i class='fa-solid fa-shield'></i> Commander Access</h2><p class='sub'>Enter the geopolitical network.</p><input id='email' class='search' placeholder='Email'><br><br><input id='password' type='password' class='search' placeholder='Password'><br><br><button id='btn' class='btn' style='width:100%'>Login</button><p id='msg' class='sub'></p><p class='sub'>No account? <a href='/register'>Register</a></p></div></div>
<script>
btn.onclick=async()=>{try{const r=await fetch('/api/auth/login',{method:'POST',headers:{'Content-Type':'application/json'},body:JSON.stringify({email:email.value,password:password.value})});const j=await r.json();if(j.error)throw new Error(j.message||j.error);location.href='/dashboard';}catch(e){msg.textContent=e.message;msg.style.color='#ef4444';}};
</script></body></html>
